answers.solution:
The bug had three root causes: the gateway spawn path logged `resp.Usage` and discarded it; `Wait()`'s completed branch returned `TickOutcome{}`; `Complete()` persisted records without `commits`/`files_changed`. The fix carries the data on `SpawnedTick` and computes/persists real values.

**1. Carry usage + model + workdir + reqStart on `SpawnedTick`** (`tick.go`, `gateway.go`):

```go
type SpawnedTick struct {
	ID       string
	Model    string
	Workdir  string
	ReqStart time.Time
	mu       sync.Mutex
	usage    *TokenUsage // set by gateway spawn path (was: logged & dropped)
}

func (t *SpawnedTick) SetUsage(u TokenUsage) { t.mu.Lock(); t.mu.Unlock(); t.usage = &u }
func (t *SpawnedTick) Usage() *TokenUsage { /* mutex-guarded copy, nil-safe */ }

// gateway spawn path — BEFORE: log.Printf("usage=%+v", resp.Usage) then nothing
func spawnTask(id, model, workdir string, reqStart time.Time, resp gatewayResponse) *SpawnedTick {
	tick := &SpawnedTick{ID: id, Model: model, Workdir: workdir, ReqStart: reqStart}
	tick.SetUsage(resp.Usage) // AFTER: carry it, don't drop it
	return tick
}
```

**2. Populate real tokens/cost/commits/files in `Wait()`'s completed branch** (`tick.go`):

```go
func (t *SpawnedTick) Wait(ctx context.Context, rates RateMap) TickOutcome {
	select {
	case <-ctx.Done():
		return TickOutcome{TickID: t.ID} // cancelled branch
	default:
	}
	now := time.Now()
	out := TickOutcome{TickID: t.ID, Completed: true, Duration: now.Sub(t.ReqStart)}

	if u := t.Usage(); u != nil { // tokens: carried from spawn path
		out.Tokens = *u
		if r, ok := rates[t.Model]; ok { // cost: per-model rate map
			out.Cost = float64(u.PromptTokens)/1000.0*r.InputPer1K +
				float64(u.CompletionTokens)/1000.0*r.OutputPer1K
		} // unknown model => $0, no crash
	}

	out.Commits, out.Files = gitMetrics(t.Workdir, t.ReqStart, now) // tick window
	return out
}

// git rev-list --count / log --name-only over [since, until); every failure => (0,0)
func gitMetrics(workdir string, since, until time.Time) (commits, files int) {
	if workdir == "" { return 0, 0 }
	commits = intOf(run("git", "-C", workdir, "rev-list", "--count",
		"--since="+since.UTC().Format(time.RFC3339), "--until="+until.UTC().Format(time.RFC3339), "--all"))
	// files: git log --since --until --name-only --pretty=format:, dedup paths
	return commits, len(uniquePaths(run("git", "-C", workdir, "log", /* same window */, "--name-only", "--pretty=format:")))
}
```

**3. Persist commits + files in `Complete()`** (`store.go`):

```go
type Store interface { Persist(TickOutcome) error }

func (t *SpawnedTick) Complete(s Store, out TickOutcome) error {
	out.PersistedAt = time.Now().UTC()
	return s.Persist(out) // record now includes Commits + Files
}
```

